    form.querySelector = (selector) => (selector === ".oc-agent-input" ? input : status);
    const root = {
      querySelectorAll(selector) {
        return selector === "[data-agent-compose-form]" ? [form] : [];
      },
    };

    expect(bindAgentComponentDemos(root)).toBe(1);
    const submit = new Event("submit", { cancelable: true });
    form.dispatchEvent(submit);

    expect(submit.defaultPrevented).toBe(true);
    expect(input.value).toBe("");
    expect(input.focused).toBe(true);
    expect(status.textContent).toBe("Message sent");
  });
  test("moves a selected suggestion into its linked composer", () => {
    const inputEvents = [];
    const input = new EventTarget();
    input.value = "";
    input.focused = false;
    input.focus = () => (input.focused = true);
    input.addEventListener("input", () => inputEvents.push(input.value));
    const suggestion = new EventTarget();
    suggestion.dataset = {
      agentSuggestionTarget: "message",
      agentSuggestionValue: "Review the implementation",
    };
    suggestion.textContent = "Review";
    const root = {
      getElementById: (id) => (id === "message" ? input : null),
      querySelectorAll(selector) {
        return selector === "[data-agent-suggestion-value]" ? [suggestion] : [];
      },
    };

    expect(bindAgentComponentDemos(root)).toBe(1);
    suggestion.dispatchEvent(new Event("click"));
    expect(input.value).toBe("Review the implementation");
    expect(input.focused).toBe(true);
    expect(inputEvents).toEqual(["Review the implementation"]);
  });
  test("finds a suggestion target when the binding root is an element", () => {
    const input = { id: "message" };
    const root = {
      querySelectorAll(selector) {
        return selector === "[id]" ? [input] : [];
      },
    };

    expect(findAgentSuggestionTarget(root, "message")).toBe(input);
    expect(findAgentSuggestionTarget(root, "missing")).toBe(null);
  });
  test("updates and closes the agent mode selector", () => {
    const label = { textContent: "Agent" };
    const summary = {
      focused: false,
      focus() {
        this.focused = true;
      },
    };
    const agent = new EventTarget();
    agent.checked = true;
    agent.value = "Agent";
    const plan = new EventTarget();
    plan.checked = false;
    plan.value = "Plan";
    const selector = {
      open: true,
      querySelector: (query) => (query === "summary" ? summary : label),
      querySelectorAll: () => [agent, plan],
    };
    const root = {
      querySelectorAll(query) {
        return query === "[data-agent-mode-selector]" ? [selector] : [];
      },
    };

    expect(bindAgentComponentDemos(root)).toBe(1);
    agent.checked = false;
    plan.checked = true;
    plan.dispatchEvent(new Event("change"));
    expect(label.textContent).toBe("Plan");
    expect(selector.open).toBe(false);
    expect(summary.focused).toBe(true);
  });
  test("updates and closes the agent model picker", () => {
    const name = { textContent: "Balanced" };
    const version = { textContent: "4.6" };
    const summary = {
      focused: false,
      focus() {
        this.focused = true;
      },
    };
    const balanced = new EventTarget();
    balanced.checked = true;
    balanced.value = "Balanced";
    balanced.dataset = { agentModelOptionVersion: "4.6" };
    const fast = new EventTarget();
    fast.checked = false;
    fast.value = "Fast";
    fast.dataset = { agentModelOptionVersion: "2.1" };
    const picker = {
      open: true,
      querySelector: (query) => {
        if (query === "[data-agent-model-name]") return name;
        if (query === "[data-agent-model-version]") return version;
        return summary;
      },
      querySelectorAll: () => [balanced, fast],
    };
    const root = {
      querySelectorAll(query) {
        return query === "[data-agent-model-picker]" ? [picker] : [];
      },
    };

    expect(bindAgentComponentDemos(root)).toBe(1);
    balanced.checked = false;
    fast.checked = true;
    fast.dispatchEvent(new Event("change"));
    expect(name.textContent).toBe("Fast");
    expect(version.textContent).toBe("2.1");
    expect(picker.open).toBe(false);
    expect(summary.focused).toBe(true);
  });
  test("removes only the selected file attachment", () => {
    let removed = false;
    const attachment = {
      remove: () => {
        removed = true;
      },
    };
    const button = new EventTarget();
    button.closest = () => attachment;
    const root = {
      querySelectorAll(query) {
        return query === "[data-agent-attachment-remove]" ? [button] : [];
      },
    };

    expect(bindAgentComponentDemos(root)).toBe(1);
    button.dispatchEvent(new Event("click"));
    expect(removed).toBe(true);
  });
  test("marks an approved plan without submitting the page", () => {
    const attributes = new Map();
    const status = { textContent: "Step 2 of 3" };
    const plan = {
      querySelector: () => status,
      setAttribute: (name, value) => attributes.set(name, value),
    };
    const button = new EventTarget();
    button.disabled = false;
    button.textContent = "Approve";
    button.closest = () => plan;
    const root = {
      querySelectorAll(query) {
        return query === "[data-agent-plan-approve]" ? [button] : [];
      },
    };

    expect(bindAgentComponentDemos(root)).toBe(1);
    button.dispatchEvent(new Event("click"));
    expect(attributes.get("data-state")).toBe("approved");
    expect(status.textContent).toBe("Approved");
    expect(button.disabled).toBe(true);
  });
  test("keeps the plan card named, expandable, and approvable", () => {
    const markup = getAgentReferenceContent("plan-tool");
    expect(markup).toContain("plan-working.md");
    expect(markup).toContain('aria-label="Expand plan" aria-expanded="false"');
    expect(markup).toContain("Read detailed plan");
    expect(markup).toContain("data-agent-plan-approve");
  });
  test("submits and skips agent questions without navigating", () => {
    const status = { textContent: "" };
    const skip = new EventTarget();
    const form = new EventTarget();
    form.dataset = {};
    form.querySelector = () => status;
    form.querySelectorAll = (selector) => {
      if (selector === "[data-agent-question-skip]") return [skip];
      return [];
    };
    const root = {
      querySelectorAll(selector) {
        return selector === "[data-agent-question-form]" ? [form] : [];
      },
    };

    expect(bindAgentComponentDemos(root)).toBe(1);
    const submit = new Event("submit", { cancelable: true });
    form.dispatchEvent(submit);
    expect(submit.defaultPrevented).toBe(true);
    expect(form.dataset.state).toBe("answered");
    expect(status.textContent).toBe("Answer submitted");

    skip.dispatchEvent(new Event("click"));
    expect(form.dataset.state).toBe("skipped");
    expect(status.textContent).toBe("Question skipped");
  });
  test("accepts file drops without reacting to dragged text", () => {
    const status = { textContent: "" };
    const target = new EventTarget();
    target.dataset = {};
    target.querySelector = () => status;
    const root = {
      querySelectorAll(selector) {
        return selector === "[data-agent-file-drop]" ? [target] : [];
      },
    };

    expect(bindAgentComponentDemos(root)).toBe(1);

    const textDrag = new Event("dragenter", { cancelable: true });
    Object.defineProperty(textDrag, "dataTransfer", {
      value: { types: ["text/plain"], files: [] },
    });
    target.dispatchEvent(textDrag);
    expect(textDrag.defaultPrevented).toBe(false);
    expect(target.dataset.dropActive).toBeUndefined();

    const textDrop = new Event("drop", { cancelable: true });
    Object.defineProperty(textDrop, "dataTransfer", {
      value: { types: ["text/plain"], files: [] },
    });
    target.dispatchEvent(textDrop);
    expect(textDrop.defaultPrevented).toBe(false);
    expect(status.textContent).toBe("");

    const fileDrag = new Event("dragenter", { cancelable: true });
    Object.defineProperty(fileDrag, "dataTransfer", {
      value: { types: ["Files"], files: [] },
    });
    target.dispatchEvent(fileDrag);
    expect(fileDrag.defaultPrevented).toBe(true);
    expect(target.dataset.dropActive).toBe("true");

    const fileDrop = new Event("drop", { cancelable: true });
    Object.defineProperty(fileDrop, "dataTransfer", {
      value: { types: ["Files"], files: [{ name: "reference.png" }] },
    });
    target.dispatchEvent(fileDrop);
    expect(fileDrop.defaultPrevented).toBe(true);
    expect(target.dataset.dropActive).toBe("false");
    expect(status.textContent).toBe("1 file attached");
  });
  test("keeps MCP results named and keyboard scrollable", () => {
    const markup = getAgentReferenceContent("mcp-tool");
    expect(markup).toContain('aria-label="MCP tool result"');
    expect(markup).toContain('tabindex="0"');
    expect(markup).toContain("design-system://tokens");
  });
});

name: ClawSweeper Dispatch

on:
  issues:
    types: [opened, reopened, edited, labeled, unlabeled]
  issue_comment:
    types: [created, edited]
  pull_request_target: # zizmor: ignore[dangerous-triggers] maintainer-owned external dispatch; no checkout or untrusted PR code execution
    types: [opened, reopened, synchronize, ready_for_review, edited, labeled, unlabeled]

permissions:
  contents: read

concurrency:
  group: clawsweeper-dispatch-${{ github.repository }}-${{ github.event_name }}-${{ github.event.comment.id || github.event.issue.number || github.event.pull_request.number || github.run_id }}-${{ endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled') && github.actor || 'dispatchable' }}
  cancel-in-progress: ${{ github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review' }}

jobs:
  dispatch:
    runs-on: ubuntu-latest
    # id-token proves this repository, event, branch, and run to the queue.
    # The job never checks out or executes pull request code.
    permissions:
      contents: read
      id-token: write
    if: ${{ !(endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled')) }}
    env:
      SUPERSEDES_IN_PROGRESS: ${{ (github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review') && 'true' || 'false' }}
    steps:
      - name: Debounce bursty metadata events
        if: ${{ github.event.action == 'labeled' || github.event.action == 'unlabeled' }}
        run: sleep 20

      - name: Require trusted issue command source
        id: trust
        env:
          EVENT_NAME: ${{ github.event_name }}
          EVENT_ACTION: ${{ github.event.action }}
          COMMENT_AUTHOR_ASSOCIATION: ${{ github.event.comment.author_association || '' }}
          ISSUE_AUTHOR_ASSOCIATION: ${{ github.event.issue.author_association || '' }}
          PR_AUTHOR_ASSOCIATION: ${{ github.event.pull_request.author_association || '' }}
        run: |
          case "$EVENT_NAME" in
            issue_comment) author_association="$COMMENT_AUTHOR_ASSOCIATION" ;;
            issues) author_association="$ISSUE_AUTHOR_ASSOCIATION" ;;
            pull_request_target) author_association="$PR_AUTHOR_ASSOCIATION" ;;
            *) author_association="" ;;
          esac
          case "$EVENT_NAME:$EVENT_ACTION:$author_association" in
            pull_request_target:*:*) allowed=true ;;
            issues:labeled:*|issues:unlabeled:*) allowed=true ;;
            issues:*:OWNER|issues:*:MEMBER|issues:*:COLLABORATOR) allowed=true ;;
            issue_comment:*:OWNER|issue_comment:*:MEMBER|issue_comment:*:COLLABORATOR) allowed=true ;;
            *) allowed=false ;;
          esac
          echo "allowed=$allowed" >> "$GITHUB_OUTPUT"
          if [ "$allowed" != "true" ]; then
            echo "::notice::Skipping ClawSweeper dispatch for untrusted $EVENT_NAME author association."
          fi

      - name: Pre-filter ClawSweeper comment
        id: comment_filter
        if: ${{ steps.trust.outputs.allowed == 'true' && github.event_name == 'issue_comment' }}
        env:
          COMMENT_BODY: ${{ github.event.comment.body }}
        run: |
          set -euo pipefail
          if [[ "$COMMENT_BODY" == *"<!-- clawsweeper-maintainer-opt-in:"* ]]; then
            echo "is_command=false" >> "$GITHUB_OUTPUT"
            exit 0
          fi
          if grep -Eiq '(^|[[:space:]])@(clawsweeper|openclaw-clawsweeper)\b(\[bot\])?|(^|[[:space:]])/(clawsweeper|review|re-review|rerun([[:space:]]+|-)?review|status|explain|fix|build|implement|create([[:space:]]+|-)?pr|fix([[:space:]]+|-)?issue|autofix|auto([[:space:]]+|-)?fix|automerge|auto([[:space:]]+|-)?merge|approve|stop|autoclose)\b' <<< "$COMMENT_BODY"; then
            echo "is_command=true" >> "$GITHUB_OUTPUT"
          else
            echo "is_command=false" >> "$GITHUB_OUTPUT"
          fi

      - name: Dispatch exact ClawSweeper review
        if: ${{ steps.trust.outputs.allowed == 'true' && github.event_name != 'issue_comment' }}
        env:
          TARGET_REPO: ${{ github.repository }}
          TARGET_BRANCH: ${{ github.event.repository.default_branch }}
          ITEM_NUMBER: ${{ github.event.issue.number || github.event.pull_request.number }}
          ITEM_KIND: ${{ github.event_name == 'pull_request_target' && 'pull_request' || 'issue' }}
          SOURCE_EVENT: ${{ github.event_name }}
          SOURCE_ACTION: ${{ github.event.action }}
          TARGET_DISPATCH_URL: https://clawsweeper.openclaw.ai/github/target-dispatch
        run: |
          set -euo pipefail
          source_identity_json="$(node <<'NODE'
          const crypto = require("node:crypto");
          const fs = require("node:fs");
          const event = JSON.parse(fs.readFileSync(process.env.GITHUB_EVENT_PATH, "utf8"));
          const pullRequest = event.pull_request && typeof event.pull_request === "object"
            ? event.pull_request
            : {};
          const issue = event.issue && typeof event.issue === "object" ? event.issue : {};
          const source = process.env.ITEM_KIND === "pull_request" ? pullRequest : issue;
          const headSha = String(pullRequest.head?.sha || "").trim().toLowerCase();
          const baseSha = String(pullRequest.base?.sha || "").trim().toLowerCase();
          const updatedAt = String(pullRequest.updated_at || "").trim();
          const queueClaim = {};
          const result = { queue_claim: queueClaim };
          const sourceUpdatedAt = String(source.updated_at || "").trim();
          if (sourceUpdatedAt && Number.isFinite(Date.parse(sourceUpdatedAt))) {
            queueClaim.source_updated_at = sourceUpdatedAt;
          }
          if (
            typeof source.title === "string" &&
            (source.body === null || typeof source.body === "string") &&
            typeof source.locked === "boolean" &&
            Array.isArray(source.labels)
          ) {
            const labels = [
              ...new Set(
                source.labels
                  .map((label) => String(label?.name || "").trim().toLowerCase())
                  .filter((label) => {
                    if (!label) return false;
                    if (label === "proof: override") return true;
                    if (/^(?:status|rating|proof|merge-risk|impact|issue-rating):/.test(label)) return false;
                    if (/^p[0-3]$/.test(label)) return false;
                    if ([
                      "maturity:stable",
                      "feature: ✨ showcase",
                      "good first issue",
                      "mantis: telegram-visible-proof",
                      "proof: telegram-e2e",
                      "triage: needs-real-behavior-proof",
                      "clawsweeper-recovery-stuck",
                      "no-stale",
                      "stale",
                    ].includes(label)) return false;
                    return !label.startsWith("clawsweeper:") || [
                      "clawsweeper:autofix",
                      "clawsweeper:automerge",
                      "clawsweeper:human-review",
                      "clawsweeper:manual-only",
                      "clawsweeper:bulk-filed",
                    ].includes(label);
                  }),
              ),
            ].sort();
            queueClaim.source_content_revision = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 2,
                  title: source.title,
                  body: source.body || "",
                  locked: source.locked,
                  close_guard_labels: labels,
                }),
              )
              .digest("hex");
          }
          if (process.env.ITEM_KIND === "pull_request") {
            if (/^[0-9a-f]{40}$/.test(headSha)) queueClaim.source_head_sha = headSha;
            if (/^[0-9a-f]{40}$/.test(baseSha)) queueClaim.source_base_sha = baseSha;
            if (typeof pullRequest.draft === "boolean") {
              queueClaim.source_is_draft = pullRequest.draft;
            }
          }
          if (
            process.env.ITEM_KIND !== "pull_request" ||
            !/^[0-9a-f]{40}$/.test(headSha) ||
            !updatedAt
          ) {
            process.stdout.write(JSON.stringify(result));
          } else {
            result.ingress_route = "target_dispatcher";
            result.ingress_fingerprint = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 1,
                  target_repo: String(process.env.TARGET_REPO || "").toLowerCase(),
                  item_number: Number(process.env.ITEM_NUMBER),
                  action: String(process.env.SOURCE_ACTION || ""),
                  head_sha: headSha,
                  updated_at: updatedAt,
                  body: typeof pullRequest.body === "string" ? pullRequest.body : "",
                  label: String(event.label?.name || ""),
                }),
              )
              .digest("hex");
            process.stdout.write(JSON.stringify(result));
          }
          NODE
          )"
          client_payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --arg target_branch "$TARGET_BRANCH" \
            --argjson item_number "$ITEM_NUMBER" \
            --arg item_kind "$ITEM_KIND" \
            --arg source_event "$SOURCE_EVENT" \
            --arg source_action "$SOURCE_ACTION" \
            --argjson source_identity "$source_identity_json" \
            --argjson supersedes_in_progress "$SUPERSEDES_IN_PROGRESS" \
            '{target_repo:$target_repo,target_branch:$target_branch,item_number:$item_number,item_kind:$item_kind,source_event:$source_event,source_action:$source_action,supersedes_in_progress:$supersedes_in_progress} + $source_identity')"
          # The App webhook remains an independent delivery route.
          if [ -n "${ACTIONS_ID_TOKEN_REQUEST_URL:-}" ] &&
            [ -n "${ACTIONS_ID_TOKEN_REQUEST_TOKEN:-}" ] &&
            oidc_token="$(curl --fail --silent --show-error --connect-timeout 5 --max-time 15 \
              --header "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" \
              --get --data-urlencode "audience=$TARGET_DISPATCH_URL" \
              "$ACTIONS_ID_TOKEN_REQUEST_URL" | jq -er '.value | strings | select(length > 0)')" &&
            [ -n "$oidc_token" ]; then
            echo "::add-mask::$oidc_token"
            direct_body="$RUNNER_TEMP/clawsweeper-direct-intake.json"
            if direct_status="$(curl --silent --show-error --connect-timeout 5 --max-time 20 \
              --request POST \
              --header "authorization: Bearer $oidc_token" \
              --header "content-type: application/json" \
              --data "$client_payload" \
              --output "$direct_body" \
              --write-out '%{http_code}' \
              "$TARGET_DISPATCH_URL")" &&
              [[ "$direct_status" == 2[0-9][0-9] ]]; then
              echo "Queued ClawSweeper intake directly: $(jq -c . "$direct_body" 2>/dev/null || echo '{}')"
              exit 0
            fi
            # Only non-transient 4xx is a deliberate refusal; the App webhook covers it.
            # Timeouts, throttling, and verifier/Worker failures must stay re-runnable.
            if [[ "${direct_status:-}" == 4[0-9][0-9] && "$direct_status" != 408 && "$direct_status" != 429 ]]; then
              echo "::warning::ClawSweeper intake declined this event (HTTP $direct_status); the App webhook route still applies."
              exit 0
            fi
            echo "::error::ClawSweeper intake unavailable (HTTP ${direct_status:-none}); re-run this job after the Worker recovers."
          else
            echo "::error::ClawSweeper OIDC token unavailable; the dispatch job needs id-token: write."
          fi
          exit 1
      - name: Dispatch ClawSweeper comment
        if: >-
          ${{
            steps.trust.outputs.allowed == 'true' &&
            github.event_name == 'issue_comment' &&
            steps.comment_filter.outputs.is_command == 'true'
          }}
        env:
          TARGET_REPO: ${{ github.repository }}
          ITEM_NUMBER: ${{ github.event.issue.number }}
          COMMENT_ID: ${{ github.event.comment.id }}
          SOURCE_ACTION: ${{ github.event.action }}
          TARGET_DISPATCH_URL: https://clawsweeper.openclaw.ai/github/target-dispatch
        run: |
          set -euo pipefail
          client_payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --argjson item_number "$ITEM_NUMBER" \
            --argjson comment_id "$COMMENT_ID" \
            --arg source_action "$SOURCE_ACTION" \
            '{target_repo:$target_repo,item_number:$item_number,comment_id:$comment_id,source_event:"issue_comment",source_action:$source_action}')"
          # The App webhook remains an independent delivery route.
          if [ -n "${ACTIONS_ID_TOKEN_REQUEST_URL:-}" ] &&
            [ -n "${ACTIONS_ID_TOKEN_REQUEST_TOKEN:-}" ] &&
            oidc_token="$(curl --fail --silent --show-error --connect-timeout 5 --max-time 15 \
              --header "Authorization: bearer $ACTIONS_ID_TOKEN_REQUEST_TOKEN" \
              --get --data-urlencode "audience=$TARGET_DISPATCH_URL" \
              "$ACTIONS_ID_TOKEN_REQUEST_URL" | jq -er '.value | strings | select(length > 0)')" &&
            [ -n "$oidc_token" ]; then
            echo "::add-mask::$oidc_token"
            direct_body="$RUNNER_TEMP/clawsweeper-direct-intake.json"
            if direct_status="$(curl --silent --show-error --connect-timeout 5 --max-time 20 \
              --request POST \
              --header "authorization: Bearer $oidc_token" \
              --header "content-type: application/json" \
              --data "$client_payload" \
              --output "$direct_body" \
              --write-out '%{http_code}' \
              "$TARGET_DISPATCH_URL")" &&
              [[ "$direct_status" == 2[0-9][0-9] ]]; then
              echo "Queued ClawSweeper intake directly: $(jq -c . "$direct_body" 2>/dev/null || echo '{}')"
              exit 0
            fi
            # Only non-transient 4xx is a deliberate refusal; the App webhook covers it.
            # Timeouts, throttling, and verifier/Worker failures must stay re-runnable.
            if [[ "${direct_status:-}" == 4[0-9][0-9] && "$direct_status" != 408 && "$direct_status" != 429 ]]; then
              echo "::warning::ClawSweeper intake declined this event (HTTP $direct_status); the App webhook route still applies."
              exit 0
            fi
            echo "::error::ClawSweeper intake unavailable (HTTP ${direct_status:-none}); re-run this job after the Worker recovers."
          else
            echo "::error::ClawSweeper OIDC token unavailable; the dispatch job needs id-token: write."
          fi
          exit 1

export const exampleDialogAttribute = "data-example-dialog";
export const exampleDialogSelector = `[${exampleDialogAttribute}]`;

export function bindExampleDialog(root = document) {
  const trigger = root.querySelector("[data-open-dialog]");
  const dialog = root.querySelector(exampleDialogSelector);
  if (!trigger || !dialog) return false;

  trigger.addEventListener("click", () => {
    dialog.showModal();
    const reduced = dialog.ownerDocument?.defaultView
      ?.matchMedia("(prefers-reduced-motion: reduce)").matches;
    dialog.animate?.(
      reduced
        ? [{ opacity: 0 }, { opacity: 1 }]
        : [
            { opacity: 0, transform: "scale(0.97)" },
            { opacity: 1, transform: "scale(1)" },
          ],
      {
        duration: reduced ? 120 : 200,
        easing: "cubic-bezier(0.23, 1, 0.32, 1)",
      },
    );
  });
  return true;
}

// Kept separate from the agent reference content so the component workbench
// can render the frame without importing the full catalog, which would close
// an import cycle through the workbench config.
import { agentIcon } from "./agent-icons.js";

// A declared brand accent is only usable with a foreground the host can put on
// it, so the specimen carries the pair a host would resolve together. This one
// clears AA on the accent it ships with; the frame default cannot, because
// --oc-text-on-accent is tuned for the OpenClaw accent rather than an
// arbitrary third-party one.
export const mcpAppBrand = { accent: "#6d28d9", accentContrast: "#ffffff" };

export function mcpAppFrame({
  name = "Table Booking",
  origin = "reservations",
  accent = "",
  accentContrast = "",
  body = "",
} = {}) {
  const custom = [
    accent ? `--oc-app-accent: ${accent}` : "",
    accentContrast ? `--oc-app-accent-contrast: ${accentContrast}` : "",
  ]
    .filter(Boolean)
    .join("; ");
  const style = custom ? ` style="${custom}"` : "";
  return `<section class="oc-mcp-app"${style}>
    <header class="oc-mcp-app-header">
      <div class="oc-mcp-app-identity">
        <span class="oc-mcp-app-mark" aria-hidden="true">${agentIcon("plug-zap")}</span>
        <span class="oc-mcp-app-name">${name}</span>
        <span class="oc-mcp-app-origin">${origin}</span>
      </div>
      <div class="oc-mcp-app-actions">
        <button type="button" aria-label="Reload app">${agentIcon("refresh-cw")}</button>
