// Guard-test surface: markup may only reference names present in this curated
// subset; unregistered names render as nothing at runtime.
export const registeredIconNames = Object.freeze(Object.keys(icons));

export function createIcons(options = {}) {
  const {
    root = document,
    nameAttr = "data-lucide",
    attrs = {},
    inTemplates = false,
  } = options;

  for (const element of root.querySelectorAll(`[${nameAttr}]`)) {
    const name = element.getAttribute(nameAttr);
    const icon = icons[name];
    if (!icon) {
      console.warn(`Lucide icon "${name}" is not registered.`);
      continue;
    }

    const elementAttrs = Object.fromEntries(
      [...element.attributes].map(({ name: attributeName, value }) => [attributeName, value]),
    );
    const className = ["lucide", `lucide-${name}`, elementAttrs.class, attrs.class]
      .filter(Boolean)
      .join(" ");
    const svg = createElement(icon, {
      "aria-hidden": elementAttrs["aria-hidden"] ?? "true",
      ...attrs,
      ...elementAttrs,
      class: className,
    });
    element.replaceWith(svg);
  }

  if (inTemplates) {
    for (const template of root.querySelectorAll("template")) {
      createIcons({ ...options, root: template.content });
    }
  }
}

export const lucide = { createIcons };

import { describe, expect, test } from "bun:test";
import {
  createPreviewHistoryState,
  readPreviewHistoryState,
  resolvePreviewRoute,
  resolvePreviewSiteRoot,
  shouldInterceptPreviewLink,
  updatePreviewHistoryScroll,
} from "../preview/router.js";
import { homePage, referencePages } from "../preview/navigation.js";

function click(overrides = {}) {
  return {
    altKey: false,
    button: 0,
    ctrlKey: false,
    defaultPrevented: false,
    metaKey: false,
    shiftKey: false,
    ...overrides,
  };
}

function link(href, overrides = {}) {
  const attributes = new Set(overrides.attributes || []);
  return {
    href,
    target: "",
    closest: () => null,
    hasAttribute: (name) => attributes.has(name),
    ...overrides,
  };
}

describe("preview router", () => {
  test("resolves a stable site root for local and GitHub Pages routes", () => {
    expect(
      resolvePreviewSiteRoot(
        "http://127.0.0.1:4173/interface/primitives/action/#usage",
        "../../../",
      ),
    ).toBe("http://127.0.0.1:4173/");
    expect(
      resolvePreviewSiteRoot(
        "https://openclaw.github.io/design-system/interface/primitives/action/",
        "../../../",
      ),
    ).toBe("https://openclaw.github.io/design-system/");

    expect(
      resolvePreviewSiteRoot(
        "https://openclaw.github.io/design-system/interface/primitives/action/index.html",
      ),
    ).toBe("https://openclaw.github.io/design-system/");
    expect(
      resolvePreviewSiteRoot(
        "http://127.0.0.1:4173/terminal-ui/notices-and-output//terminal-ui/notices-and-output/",
      ),
    ).toBe("http://127.0.0.1:4173/");
    expect(
      resolvePreviewSiteRoot("https://openclaw.github.io/design-system/index.html"),
    ).toBe("https://openclaw.github.io/design-system/");
  });

  test("maps canonical, extensionless, index, and hashed URLs to known pages", () => {
    const siteRoot = "https://openclaw.github.io/design-system/";

    expect(resolvePreviewRoute(`${siteRoot}introduction`, siteRoot)).toMatchObject({
      pageId: "introduction",
      path: "introduction/",
      hash: "",
    });
    expect(resolvePreviewRoute(`${siteRoot}foundations/`, siteRoot)).toMatchObject({
      pageId: "introduction",
      path: "introduction/",
      href: `${siteRoot}introduction/`,
    });
    expect(resolvePreviewRoute(`${siteRoot}foundations/colors`, siteRoot)).toMatchObject({
      pageId: "foundation-colors",
      path: "foundations/colors/",
      hash: "",
    });
    expect(resolvePreviewRoute(`${siteRoot}agent-components/bash-tool/`, siteRoot)).toMatchObject({
      pageId: "interactive-tool",
      path: "agent-components/interactive-tool/",
      href: `${siteRoot}agent-components/interactive-tool/`,
    });
    expect(
      resolvePreviewRoute(`${siteRoot}interface/primitives/action/index.html#usage`, siteRoot),
    ).toMatchObject({
      pageId: "primitive-action",
      path: "interface/primitives/action/",
      hash: "#usage",
    });
    expect(
      resolvePreviewRoute(
        `${siteRoot}terminal-ui/notices-and-output//terminal-ui/notices-and-output/`,
        siteRoot,
      ),
    ).toMatchObject({
      pageId: "terminal-notices-output",
      path: "terminal-ui/notices-and-output/",
      href: `${siteRoot}terminal-ui/notices-and-output/`,
    });
    expect(resolvePreviewRoute(`${siteRoot}#home`, siteRoot)).toMatchObject({
      pageId: "overview",
      path: "",
      hash: "#home",
    });

    expect(resolvePreviewRoute("https://openclaw.github.io/foundations/colors/", siteRoot)).toBeNull();
    expect(resolvePreviewRoute(`${siteRoot}assets/openclaw-mark.png`, siteRoot)).toBeNull();
    expect(resolvePreviewRoute(`${siteRoot}missing/`, siteRoot)).toBeNull();

    expect(
      resolvePreviewRoute(
        "http://127.0.0.1:4173/interface/primitives/action/",
        "http://127.0.0.1:4173/",
      )?.pageId,
    ).toBe("primitive-action");
  });

  test("resolves every page published by the navigation manifest", () => {
    const siteRoot = "https://openclaw.github.io/design-system/";

    for (const page of [homePage, ...referencePages]) {
      expect(resolvePreviewRoute(new URL(page.path, siteRoot), siteRoot)?.pageId).toBe(page.id);
    }
  });

  test("intercepts only unmodified same-origin links to known preview pages", () => {
    const siteRoot = "https://openclaw.github.io/design-system/";
    const page = link(`${siteRoot}interface/primitives/action/#usage`);

    expect(shouldInterceptPreviewLink(click(), page, siteRoot)).toBe(true);

    for (const modifier of ["altKey", "ctrlKey", "metaKey", "shiftKey"]) {
      expect(shouldInterceptPreviewLink(click({ [modifier]: true }), page, siteRoot)).toBe(false);
    }
    expect(shouldInterceptPreviewLink(click({ button: 1 }), page, siteRoot)).toBe(false);
    expect(shouldInterceptPreviewLink(click({ defaultPrevented: true }), page, siteRoot)).toBe(false);
    expect(shouldInterceptPreviewLink(click(), link(page.href, { target: "_blank" }), siteRoot)).toBe(
      false,
    );
    expect(
      shouldInterceptPreviewLink(click(), link(page.href, { attributes: ["download"] }), siteRoot),
    ).toBe(false);
    expect(
      shouldInterceptPreviewLink(
        click(),
        link(page.href, { closest: (selector) => selector === "[data-workbench-inert-link]" }),
        siteRoot,
      ),
    ).toBe(false);
    expect(
      shouldInterceptPreviewLink(click(), link("https://example.com/components/"), siteRoot),
    ).toBe(false);
    expect(
      shouldInterceptPreviewLink(click(), link(`${siteRoot}assets/openclaw-mark.png`), siteRoot),
    ).toBe(false);
    expect(shouldInterceptPreviewLink(click(), link(`${siteRoot}unknown/`), siteRoot)).toBe(false);
  });

  test("stores validated route, scroll, and hash data without replacing other history state", () => {
    const state = createPreviewHistoryState(
      "primitive-action",
      { hash: "usage", scrollX: 12, scrollY: 480 },
      { analytics: "preserved" },
    );

    expect(state.analytics).toBe("preserved");
    expect(readPreviewHistoryState(state)).toEqual({
      pageId: "primitive-action",
      hash: "#usage",
      scrollX: 12,
      scrollY: 480,
    });

    const scrolled = updatePreviewHistoryScroll(state, 4, 920);
    expect(readPreviewHistoryState(scrolled)).toEqual({
      pageId: "primitive-action",
      hash: "#usage",
      scrollX: 4,
      scrollY: 920,
    });
    expect(scrolled.analytics).toBe("preserved");

    expect(readPreviewHistoryState({ pageId: "primitive-action" })).toBeNull();
    expect(readPreviewHistoryState({ carapacePreview: { pageId: "missing" } })).toBeNull();
    expect(() => createPreviewHistoryState("missing")).toThrow("Unknown preview page");
  });
});

import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, test } from "bun:test";
import { bindApplicationModelControls } from "../preview/application-model-controls.js";
import {
  bindApplicationComposer,
  bindApplicationNavigation,
  getWorkbenchControlOptions,
  getWorkbenchDefinition,
  normalizeWorkbenchState,
} from "../preview/component-workbench-config.js";
import { isComponentWorkbenchPage } from "../preview/component-workbench.js";
import { registeredIconNames } from "../preview/lucide.js";
import { referencePages } from "../preview/navigation.js";

// These guards exist because workbench markup is plain strings and binders
// query it by attribute: nothing else fails when the two drift apart. Every
// binder selector must be reachable in at least one rendered state, and every
// icon name must resolve in the curated lucide registry (unregistered names
// render as nothing).

const sharedBinderSources: Record<string, string> = {
  bindApplicationModelControls: bindApplicationModelControls.toString(),
  bindApplicationComposer: bindApplicationComposer.toString(),
  bindApplicationNavigation: bindApplicationNavigation.toString(),
};

// Hooks a shared binder queries that a page intentionally never renders.
const binderSelectorExceptions: Record<string, string[]> = {
  // Quick Chat has no talk mode, camera, or hold-to-dictate live status.
  "application-quick-chat": [
    "data-workbench-composer-talk",
    "data-workbench-composer-camera",
    "data-workbench-composer-dictation-status",
  ],
};

const workbenchPageIds = referencePages
  .map(({ id }) => id)
  .filter((id) => isComponentWorkbenchPage(id) && getWorkbenchDefinition(id));

function binderSourceFor(definition: { bind?: (...args: unknown[]) => void }) {
  if (!definition.bind) return "";
  let source = definition.bind.toString();
  for (const [name, sharedSource] of Object.entries(sharedBinderSources)) {
    if (source.includes(name)) source += sharedSource;
  }
  return source;
}

function stateVariants(definition: {
  controls: { id: string; type: string; options?: unknown }[];
}) {
  const base = normalizeWorkbenchState(definition);
  const variants: Record<string, unknown>[] = [{ ...base }];
  const axes = definition.controls.map((control) => ({
    id: control.id,
    values:
      control.type === "toggle"
        ? [true, false]
        : getWorkbenchControlOptions(control).map(({ value }) => value),
  }));
  for (const axis of axes) {
    for (const value of axis.values) {
      variants.push({ ...base, [axis.id]: value });
    }
  }
  // Pairwise combinations catch hooks that only render when two states align,
  // e.g. camera controls need voice active while the session is not busy.
  for (let left = 0; left < axes.length; left += 1) {
    for (let right = left + 1; right < axes.length; right += 1) {
      for (const leftValue of axes[left].values) {
        for (const rightValue of axes[right].values) {
          variants.push({
            ...base,
            [axes[left].id]: leftValue,
            [axes[right].id]: rightValue,
          });
        }
      }
    }
  }
  return variants;
}

function renderedCorpus(pageId: string) {
  const definition = getWorkbenchDefinition(pageId);
  if (!definition?.markup) return "";
  return stateVariants(definition)
    .map((state) => definition.markup(state))
    .join("\n");
}

describe("workbench markup and binder contract", () => {
  test("every binder hook selector renders in at least one state", () => {
    const failures: string[] = [];
    for (const pageId of workbenchPageIds) {
      const definition = getWorkbenchDefinition(pageId);
      const source = binderSourceFor(definition);
      if (!source) continue;
      const selectors = new Set(
        [...source.matchAll(/\[(data-workbench-[a-z-]+)\]/g)].map((match) => match[1]),
      );
      if (selectors.size === 0) continue;
      const corpus = renderedCorpus(pageId);
      const allowed = new Set(binderSelectorExceptions[pageId] ?? []);
      for (const selector of selectors) {
        if (allowed.has(selector)) continue;
        if (!corpus.includes(selector)) {
          failures.push(`${pageId}: binder queries ${selector} but no state renders it`);
        }
      }
    }
    expect(failures).toEqual([]);
  });

  test("all icon names in rendered and source markup are registered", () => {
    const registered = new Set(registeredIconNames);
    const failures = new Set<string>();
    const collect = (markup: string, origin: string) => {
      for (const match of markup.matchAll(/data-lucide="([a-z0-9-]+)"/g)) {
        if (!registered.has(match[1])) failures.add(`${origin}: ${match[1]}`);
      }
    };
    for (const pageId of workbenchPageIds) collect(renderedCorpus(pageId), pageId);
    const previewDir = join(import.meta.dir, "../preview");
    for (const file of readdirSync(previewDir)) {
      if (!/\.(js|jsx|html)$/.test(file)) continue;
      collect(readFileSync(join(previewDir, file), "utf8"), file);
    }
    expect([...failures].sort()).toEqual([]);
  });
});

import { describe, expect, test } from "bun:test";
import { initChartHover } from "../js/charts.js";

function chartFixture(data) {
  const children = [];
  const listeners = new Map();
  const attributes = new Map([
    ["data-oc-hover", data],
    ["data-oc-hover-unit", "events"],
  ]);
  const band = {
    dataset: {},
    getAttribute: (name) => attributes.get(name),
    getBoundingClientRect: () => ({ left: 20, width: 300 }),
    append: (...elements) => children.push(...elements),
    addEventListener: (name, listener) => listeners.set(name, listener),
  };
  const document = {
    querySelectorAll: () => [band],
    createElement: () => ({ hidden: false, style: {}, textContent: "" }),
  };
  return { attributes, band, children, document, listeners };
}

function withChart(data, run) {
  const fixture = chartFixture(data);
  const previous = Object.getOwnPropertyDescriptor(globalThis, "document");
  Object.defineProperty(globalThis, "document", { configurable: true, value: fixture.document });
  try {
    run(fixture);
  } finally {
    if (previous) Object.defineProperty(globalThis, "document", previous);
    else delete globalThis.document;
  }
}

describe("chart hover", () => {
  test("shows the matching period and numeric string value, and binds only once", () => {
    withChart('[["Monday",1200],["Tuesday","3400"]]', ({ document, children, listeners }) => {
      initChartHover(document);
      initChartHover(document);
      expect(children).toHaveLength(2);
      const [cursor, tip] = children;
      listeners.get("mousemove")({ clientX: 20 });
      expect(tip.textContent).toBe("Monday · 1,200 events");
      expect(tip.hidden).toBe(false);
      expect(cursor.style.left).toBe("75.0px");
      listeners.get("mousemove")({ clientX: 320 });
      expect(tip.textContent).toBe("Tuesday · 3,400 events");
      expect(cursor.style.left).toBe("225.0px");
      listeners.get("mouseleave")();
      expect(tip.hidden).toBe(true);
      expect(cursor.hidden).toBe(true);
    });
  });

  for (const data of [
    "{",
    "null",
    "[]",
    "[null]",
    "[42]",
    '["Monday"]',
    '[[]]',
    '[["Monday"]]',
    '[["Monday",1],null]',
    '[[{"toString":null},1]]',
    '[["Monday",{"toString":null}]]',
  ]) {
    test(`ignores invalid data and allows initialization after correction: ${data}`, () => {
      withChart(data, ({ attributes, band, document, children, listeners }) => {
        expect(() => initChartHover(document)).not.toThrow();
        expect(children).toHaveLength(0);
        expect(listeners.size).toBe(0);
        expect(band.dataset.ocHoverBound).not.toBe("true");

        attributes.set("data-oc-hover", '[["Monday",1200],["Tuesday",3400]]');
        initChartHover(document);
        expect(children).toHaveLength(2);
        expect(band.dataset.ocHoverBound).toBe("true");
        listeners.get("mousemove")({ clientX: 250 });
        expect(children[1].textContent).toBe("Tuesday · 3,400 events");
      });
    });
  }
});
